package net.civeira.phylax.features.oauth.oidc.domain;

/**
 * SPI for contributing fields to the OIDC discovery document.
 *
 * Each bounded context that owns an endpoint or capability registers a CDI bean implementing this
 * interface. The controller collects all contributors and calls each one to populate the discovery
 * document without coupling the controller to every context.
 */
public interface DiscoveryContributor {

  /**
   * Populates the fields this context owns in the discovery document.
   *
   * Implementations must only set the fields they own. The {@code base} URL is the tenant-specific
   * prefix (e.g. {@code https://host/oauth/openid/mytenant/}) used to construct endpoint URLs.
   *
   * @param builder mutable builder for the discovery document
   * @param base tenant-specific base URL (ends with {@code /})
   */
  void contribute(OpenIdConfiguration.OpenIdConfigurationBuilder builder, String base);
}
